patch:
diff --git a/sql/parse_tree_helpers.cc b/sql/parse_tree_helpers.cc
index 3450896dcb53..4901b4d61f60 100644
--- a/sql/parse_tree_helpers.cc
+++ b/sql/parse_tree_helpers.cc
@@ -456,7 +456,7 @@ bool apply_privileges(THD *thd,
   for (PT_role_or_privilege *p : privs)
   {
     Privilege *privilege= p->get_privilege(thd);
-    if (p == NULL)
+    if (privilege == NULL)
       return true;

     if (privilege->type == Privilege::DYNAMIC)
diff --git a/sql/parse_tree_nodes.h b/sql/parse_tree_nodes.h
index f7192913789c..ecddeedc5ab6 100644
--- a/sql/parse_tree_nodes.h
+++ b/sql/parse_tree_nodes.h
@@ -3445,12 +3445,12 @@ class PT_role_or_privilege : public Parse_tree_node

   virtual st_lex_user *get_user(THD *thd)
   {
-    thd->syntax_error_at(pos, "role or user name with the ON clause");
+    thd->syntax_error_at(pos, "Illegal authorization identifier");
     return NULL;
   }
   virtual Privilege *get_privilege(THD *thd)
   {
-    thd->syntax_error_at(pos, "privilege name without the ON clause");
+    thd->syntax_error_at(pos, "Illegal privilege identifier");
     return NULL;
   }
 };

